(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.018+t*0.3)*18 + Math.cos(y*0.013-t*0.22)*12;
  const w1y = Math.cos(y*0.02-t*0.28)*16 + Math.sin(x*0.016+t*0.32)*11;
  const w2x = Math.sin((x+y)*0.01+t*0.15)*8;
  const w2y = Math.cos((x-y)*0.012-t*0.18)*9;
  const sx = x+w1x+w2x, sy = y+w1y+w2y;
  const src = [
    [160+Math.sin(t*0.6)*110, 80+Math.cos(t*0.4)*55, 0.075, 2.1, 0.5],
    [320+Math.cos(t*0.5)*110, 160+Math.sin(t*0.7)*55, 0.095, 1.8, 0.6],
    [240+Math.sin(t*0.3+2)*150, 120+Math.cos(t*0.5+1)*95, 0.055, 2.4, 0.4],
    [120+Math.cos(t*0.8+1)*90, 180+Math.sin(t*0.6+3)*65, 0.11, 1.6, 0.7],
    [360+Math.sin(t*0.4+4)*100, 60+Math.cos(t*0.9+2)*75, 0.065, 2.7, 0.35],
    [240+Math.cos(t*0.35+5)*130, 200+Math.sin(t*0.55)*85, 0.085, 2.0, 0.55],
    [80+Math.sin(t*0.55+3)*70, 40+Math.cos(t*0.65+2)*50, 0.13, 1.4, 0.8],
    [400+Math.cos(t*0.45+1)*85, 200+Math.sin(t*0.75+4)*60, 0.07, 2.5, 0.45]
  ];
  let aS=0, iS=0, harm=0;
  for (const [sX,sY,f,sp,ph] of src) {
    const d = Math.sqrt((sx-sX)**2+(sy-sY)**2);
    const w1 = Math.sin(d*f-t*sp+ph);
    const w2 = Math.sin(d*f*1.618-t*sp*0.618+ph*2);
    aS += w1*0.6+w2*0.4;
    iS += Math.sin(d*f*0.7+t*sp*0.6+ph+1.5);
    harm += Math.cos(d*f*0.5-t*sp*0.3+ph*3)*0.5;
  }
  const n=8; const act=aS/n, inh=iS/n, hrm=harm/n;
  const bg = (Math.sin(sx*0.035+sy*0.022+t*0.9)+Math.sin(sx*0.028-sy*0.038+t*1.2))/2
    + Math.sin((sx+sy)*0.11+t*2.7)*0.25 + Math.sin((sx-sy)*0.09-t*2.2)*0.25;
  const dist=Math.sqrt((sx-cx)**2+(sy-cy)**2), ang=Math.atan2(sy-cy,sx-cx);
  const spiral = (Math.sin(dist*0.045-ang*3.5-t*1.6)+Math.sin(dist*0.038+ang*4.5-t*1.3))*0.35
    + Math.sin(dist*0.08-ang*2+t*2.5)*0.15;
  const moire = Math.sin(Math.sin(sx*0.08+t*0.5)*12+Math.cos(sy*0.07-t*0.4)*10)*0.2;
  const lap = (Math.sin(sx*0.2+1)*Math.sin(sy*0.2+2)+Math.sin(sx*0.2-1)*Math.sin(sy*0.2-2)
    +Math.sin(sx*0.2+2)*Math.sin(sy*0.2)+Math.sin(sx*0.2-2)*Math.sin(sy*0.2))/4;
  const rd = act - inh*0.65 + bg*0.25 + spiral + moire + lap*0.3 + hrm*0.4;
  const reaction = Math.tanh(rd*2.0);
  const cell = Math.tanh((Math.sin(sx*0.14)*Math.sin(sy*0.14)+Math.sin((sx+sy)*0.095+t)*0.5+Math.sin((sx*2-sy)*0.06-t*0.7)*0.3)*1.6)*0.3;
  const micro = Math.sin(sx*0.3+t*3)*Math.sin(sy*0.3-t*2.5)*0.08;
  const blend = reaction*0.65+cell*0.25+micro;
  const v = blend*0.5+0.5;
  const pal = [[6,12,52],[12,55,95],[18,110,125],[35,165,155],[140,195,120],[210,195,80],[225,140,65],[195,75,75],[130,35,65],[70,18,55],[30,10,45],[6,12,52]];
  const idx=v*(pal.length-1), i=Math.min(idx|0,pal.length-2), f=idx-i;
  const lum=0.75+Math.sin(reaction*Math.PI)*0.25;
  const edge=Math.abs(reaction)>0.75?1.2:Math.abs(reaction)>0.5?1.05:1.0;
  const glow=Math.max(0,reaction-0.5)*0.3;
  return [
    Math.min(255,((pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*lum*edge+glow*60)|0),
    Math.min(255,((pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*lum*edge+glow*40)|0),
    Math.min(255,((pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*lum*edge+glow*80)|0)
  ];
}
